import{St as e,at as t,it as n,ot as r,st as i,t as a,tt as o,vt as s}from"./chunks/framework.DkAysg6d.js";var c=JSON.parse(`{"title":"Reading this site","description":"","frontmatter":{},"headers":[],"relativePath":"reading-this-site.md","filePath":"pages/reading-this-site.md"}`),l={name:`reading-this-site.md`};function u(a,c,l,u,d,f){let p=e(`GridDemo`);return s(),n(`div`,null,[c[0]||=o(`h1`,{id:`reading-this-site`,tabindex:`-1`},[r(`Reading this site `),o(`a`,{class:`header-anchor`,href:`#reading-this-site`,"aria-label":`Permalink to “Reading this site”`},`​`)],-1),c[1]||=o(`p`,null,`Every concept page carries a grid you can drive and a source file you can edit. The panel is the documentation; the prose around it says what to look at.`,-1),i(p,{id:`multi-sort`}),c[2]||=t(`<h2 id="the-panel-part-by-part" tabindex="-1">The panel, part by part <a class="header-anchor" href="#the-panel-part-by-part" aria-label="Permalink to “The panel, part by part”">​</a></h2><table tabindex="0"><thead><tr><th>part</th><th>what it shows</th></tr></thead><tbody><tr><td>title and summary</td><td>the one sentence the example itself declares</td></tr><tr><td>the stage</td><td>a real grid, mounted from the same file that ships in <code>examples/</code></td></tr><tr><td>the timing strip</td><td>milliseconds for the stages that ran, plus a live frame rate</td></tr><tr><td>the tabs</td><td><code>Preview</code> shows the grid, <code>Edit</code> shows the source in an editor</td></tr><tr><td><code>Reset</code></td><td>restores the shipped source and remounts it</td></tr></tbody></table><h2 id="editing-one" tabindex="-1">Editing one <a class="header-anchor" href="#editing-one" aria-label="Permalink to “Editing one”">​</a></h2><p>Open <code>Edit</code>, change a value, and stop typing. Three hundred milliseconds later the previous grid is torn down and a new one is built from your text. A syntax error prints beside the stage and leaves the running grid alone, so a half-typed line never blanks the page.</p><p>Try it on the panel above: change the seeded sort to a single descending key on <code>size</code>, and the header band and the row order both move.</p><p>An edit that takes longer than two seconds stops re-running on its own and offers a <code>Run</code> button, so a slow edit cannot repeat itself into a stall.</p><h2 id="where-the-source-comes-from" tabindex="-1">Where the source comes from <a class="header-anchor" href="#where-the-source-comes-from" aria-label="Permalink to “Where the source comes from”">​</a></h2><p>No page copies an example&#39;s text. Each example imports its own file as a string, so the panel shows the file you would commit, and an edit to <code>examples/2_multi_sort.ts</code> changes the page with no doc edit at all.</p><p>The registry is <code>examples/index.ts</code>. A page names an example by its id, and an id that does not exist renders a visible error rather than an empty box.</p><h2 id="pages-with-no-panel" tabindex="-1">Pages with no panel <a class="header-anchor" href="#pages-with-no-panel" aria-label="Permalink to “Pages with no panel”">​</a></h2><p>Reference, Why, and Receipts pages carry no grid. A leaf under a concept group with no panel says in one sentence that the feature is not built, and names what is missing.</p><h2 id="the-full-screen-routes" tabindex="-1">The full-screen routes <a class="header-anchor" href="#the-full-screen-routes" aria-label="Permalink to “The full-screen routes”">​</a></h2><p>Four larger applications live under <a href="/hafley-rxjs/signal-grid/showcase-everything">Showcase</a>. Each one mounts a grid over real data volumes with a control panel and a readout, which is where scale and interaction are easier to judge than in a page-sized panel.</p>`,13)])}var d=a(l,[[`render`,u]]);export{c as __pageData,d as default};